    | 'CANCELLED'
    // 500
    | 'UNKNOWN'
    | 'INTERNAL'
    | 'DATA_LOSS'
    // 501
    | 'UNIMPLEMENTED'
    // 503
    | 'UNAVAILABLE'
    // 504
    | 'DEADLINE_EXCEEDED'
    | (string & {});
  /** User-facing message to be displayed. */
  message: string;
  /** When true, agent execution is halting because of the error. */
  fatal: boolean;
}

export interface Usage {
  model: string;
  inputTokens?: number;
  outputTokens?: number;
  cachedTokens?: number;
  cost?: { amount: number; currency?: string };
}

export interface StreamStart {
  streamId: string;
}

