import type { Part } from '@google/genai';
import type { ContentPart } from './types.js';

/**
 * Converts an array of Gemini {@link Part}s into the internal
 * {@link ContentPart} representation.
 *
 * - `functionCall` and `functionResponse` parts are skipped, as they are
 *   represented separately as tool requests/responses.
 * - Unknown part shapes are serialized to a `text` ContentPart and marked as
 *   unknown via `_meta` so no information is silently lost.
 */
export function geminiPartsToContentParts(parts: Part[]): ContentPart[] {
  const result: ContentPart[] = [];

  for (const part of parts) {
    // Skip tool call/response parts -- these are handled separately.
    if (part.functionCall !== undefined || part.functionResponse !== undefined) {
      continue;
    }

    if (part.thought) {
      const thoughtPart: ContentPart = {
        type: 'thought',
        thought: part.text ?? '',
      };
      if (part.thoughtSignature !== undefined) {
        thoughtPart.thoughtSignature = part.thoughtSignature;
      }
      result.push(thoughtPart);
      continue;
    }

    if (part.text !== undefined) {
      result.push({ type: 'text', text: part.text });
      continue;
    }

    if (part.inlineData !== undefined) {
      result.push({
        type: 'media',
        data: part.inlineData.data,
        mimeType: part.inlineData.mimeType,
      });
      continue;
    }

    if (part.fileData !== undefined) {
      result.push({
        type: 'media',
        uri: part.fileData.fileUri,
        mimeType: part.fileData.mimeType,
      });
      continue;
    }

    // Unknown part type -- preserve it as text and mark it as unknown.
    result.push({
      type: 'text',
      text: JSON.stringify(part),
      _meta: { unknown: true },
    });
  }

  return result;
}

/**
 * Converts an array of internal {@link ContentPart}s back into Gemini
 * {@link Part}s.
 *
 * - `media` parts with neither `data` nor `uri` are skipped, as they cannot be
 *   represented as a Gemini part.
 * - Unknown ContentPart variants are serialized to a `text` Gemini part.
 */
export function contentPartsToGeminiParts(contentParts: ContentPart[]): Part[] {
  const result: Part[] = [];

  for (const part of contentParts) {
    switch (part.type) {
      case 'text': {
        result.push({ text: part.text });
        break;
      }
      case 'thought': {
        const geminiPart: Part = { text: part.thought, thought: true };
        if (part.thoughtSignature !== undefined) {
          geminiPart.thoughtSignature = part.thoughtSignature;
        }
        result.push(geminiPart);
        break;
      }
      case 'media': {
        if (part.data !== undefined) {
          result.push({
            inlineData: {
              data: part.data,
              mimeType: part.mimeType ?? 'application/octet-stream',
            },
          });
        } else if (part.uri !== undefined) {
          result.push({
            fileData: {
              fileUri: part.uri,
              mimeType: part.mimeType,
            },
          });
        }
        // Media with neither data nor uri is skipped.
        break;
      }
      default: {
        // Unknown ContentPart variant -- preserve it as serialized text.
        result.push({ text: JSON.stringify(part) });
        break;
      }
    }
  }

  return result;
}

/**
 * Normalizes a tool result's display value into {@link ContentPart}s.
 *
 * - `undefined` / `null` values produce `undefined`.
 * - Strings are wrapped in a single `text` ContentPart.
 * - Objects are JSON-stringified into a single `text` ContentPart.
 */
export function toolResultDisplayToContentParts(
  value: unknown,
): ContentPart[] | undefined {
  if (value === undefined || value === null) {
    return undefined;
  }

  if (typeof value === 'string') {
    return [{ type: 'text', text: value }];
  }

  return [{ type: 'text', text: JSON.stringify(value) }];
}

export interface ToolResponseDataInput {
  errorType?: string;
  outputFile?: string;
  contentLength?: number;
  data?: Record<string, unknown>;
}

/**
 * Builds the structured `data` payload for a tool response from the recognized
 * fields of {@link ToolResponseDataInput}.
 *
 * Returns `undefined` when none of the recognized fields are present, so that
 * callers can omit the `data` field entirely.
 */
export function buildToolResponseData(
  input: ToolResponseDataInput,
): Record<string, unknown> | undefined {
  const result: Record<string, unknown> = {};

  if (input.errorType !== undefined) {
    result['errorType'] = input.errorType;
  }
  if (input.outputFile !== undefined) {
    result['outputFile'] = input.outputFile;
  }
  if (input.contentLength !== undefined) {
    result['contentLength'] = input.contentLength;
  }
  if (input.data !== undefined) {
    Object.assign(result, input.data);
  }

  if (Object.keys(result).length === 0) {
    return undefined;
  }

  return result;
}
